// PF Config: the one place for all settings of the Participant follow-up workflows.
// Change values here only.

const mockMode = true;

const base = {
  // Safety guard. While mockMode is true, sends go only to these addresses.
  allowedParticipantEmailPattern: '^aniol\\.moner\\+[^@]+@n8n\\.io$',
  allowedHostEmails: ['aniol.moner@n8n.io'],

  // Person who gets the Tremendous refill DM.
  adminEmail: 'aniol.moner@n8n.io',

  // Store
  dataTableName: 'MOCK - PF Sessions',
  dataTableId: 'L3Sa3FfY5RtqeUgk',

  // Calendly
  // Continuous discovery = bookings for this one event type, and nothing else:
  // https://calendly.com/d/dz6d-wr6-6bf/research-with-n8n
  cdEventTypeUuid: 'ebd64db8-7c09-4e31-bc2e-339065fbb930',
  roundRobinEventTypeUuid: 'ebd64db8-7c09-4e31-bc2e-339065fbb930', // old name, used by PF Calendly Capture
  uxrUtmSource: 'uxr_recruiting',

  // Timing
  timezone: 'Europe/Madrid',
  askDelayMinutes: 15,
  showupWindowHours: 6,
  finalTimeoutMinutes: 24 * 60,
  manualLookbackDays: 30,

  // Reward
  rewardDefaultUsd: 50,
  rewardMaxUsd: 100,
  currency: 'USD',
  tremendousMode: 'stub', // stub | sandbox | live
  tremendousCampaignId: 'NRF2R8ZSE9XK',
  tremendousFundingSourceId: 'balance',
  tremendousSandboxBaseUrl: 'https://testflight.tremendous.com/api/v2/',
  balanceThresholdUsd: 500,
  mockBalanceUsd: 900,

  // Email
  emailFrom: 'n8n Research <noreply@info.n8n.io>',
  emailReplyTo: 'design@n8n.io',
};

// Short delays so a full test takes minutes, not hours.
const mockOverrides = {
  askDelayMinutes: 1,
  finalTimeoutMinutes: 3,
};

const config = mockMode ? { ...base, ...mockOverrides } : { ...base };
config.mockMode = mockMode;

// Mock mode never pays real money.
if (mockMode && config.tremendousMode === 'live') {
  config.tremendousMode = 'stub';
}

return [{ json: config }];
